import{seeded as M}from"./city.min.js";import{dayOfYear as d,mix as x}from"./daylight.min.js";export const WEATHER={seed:20260929,chance:{mean:.35,swing:.25},start:[0,22],hours:[3,10],strength:[.45,1],lead:1.5,ramp:.75};export function wetChance(t,n=WEATHER){const r=Math.cos(2*Math.PI*(d(t)-355)/365);return n.chance.mean+n.chance.swing*r}export function mixSeed(t){let n=t>>>0;return n=Math.imul(n^n>>>16,73244475),n=Math.imul(n^n>>>16,73244475),((n^n>>>16)>>>0)%2147483646+1}export function daySpell(t,n=WEATHER){const r=t.getFullYear()*1e4+(t.getMonth()+1)*100+t.getDate(),s=M(mixSeed(n.seed+r));if(s()>=wetChance(t,n))return null;const o=([c,h])=>c+s()*(h-c),e=o(n.start);return{start:e,end:e+o(n.hours),strength:o(n.strength)}}function p(t,n,r){const s=Math.min(1,Math.max(0,(t-n)/r));return s*s*(3-2*s)}export function weatherAt(t,n=null,r=WEATHER){if(n==="rain")return{overcast:1,rain:1};if(n==="clear")return{overcast:0,rain:0};const s=t.getHours()+t.getMinutes()/60+t.getSeconds()/3600;let a=0,o=0;const e=new Date(t.getFullYear(),t.getMonth(),t.getDate()-1);for(const[c,h]of[[t,0],[e,24]]){const m=daySpell(c,r);if(!m)continue;const u=s+h,{start:l,end:f,strength:g}=m,{lead:i,ramp:y}=r;o=Math.max(o,g*Math.min(p(u,l,y),1-p(u,f-y,y))),a=Math.max(a,Math.min(p(u,l-i,i),1-p(u,f,i)))}return{overcast:Math.max(a,o),rain:o}}export function grayOf(t,n=1){const r=t>>16&255,s=t>>8&255,a=t&255,o=Math.min(255,(.2126*r+.7152*s+.0722*a)*n),e=c=>Math.min(255,Math.round(o*c));return e(.94)<<16|e(.97)<<8|e(1.04)}export function weathered(t,{overcast:n,rain:r}){const s=n;return{...t,skyTop:x(t.skyTop,grayOf(t.skyBottom,.82),.9*s),skyBottom:x(t.skyBottom,grayOf(t.skyBottom,.9),.85*s),clouds:x(t.clouds,grayOf(t.clouds,.72),.8*s),sun:t.sun*(1-.7*s),halo:t.halo*(1-s),hemi:t.hemi*(1-.25*s),fill:t.fill*(1-.2*s),stars:t.stars*(1-s),moonShine:t.moonShine*(1-.9*s),cityLights:Math.min(1,t.cityLights+.3*s),overcast:n,rain:r}}export const RAIN={count:1400,box:{x:[-40,70],y:[-45,30],z:[-100,20]},fall:9,length:1.6,slant:.18};export function rainStreaks(t=RAIN,n=20260930){const r=M(n),{x:s,y:a,z:o}=t.box,e=([c,h])=>c+r()*(h-c);return Array.from({length:t.count},()=>[e(s),e(a),e(o),r()])}export function streakPositions(t,n,r=RAIN,s=new Float32Array(t.length*6)){const[a,o]=r.box.y,e=o-a;return t.forEach(([c,h,m,u],l)=>{const f=((o-h+n*r.fall+u*e)%e+e)%e,g=o-f,i=l*6;s[i]=c,s[i+1]=g,s[i+2]=m,s[i+3]=c,s[i+4]=g-r.length,s[i+5]=m+r.length*r.slant}),s}
